package com.tgca.collection

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64

/**
 * Ícones ORIGINAIS dos jogos (extraídos dos pacotes originais de
 * algorithomus.com.br). Como são arquivos WebP binários, são embutidos em
 * base64 e decodificados em memória na primeira utilização.
 *
 * Obs.: a base64 do Frutris é dividida em blocos porque uma única constante
 * de string não pode exceder 65535 bytes na JVM.
 */
object IconAssets {

    private const val COBRINHA_WEBP_B64 = ""

    private val FRUTRIS_WEBP_B64: String = listOf(
        "",
        "",
        "",
    ).joinToString("")

    @Volatile private var cobrinhaCache: Bitmap? = null
    @Volatile private var frutrisCache: Bitmap? = null

    fun cobrinhaIcon(): Bitmap? {
        cobrinhaCache?.let { return it }
        val bmp = decode(COBRINHA_WEBP_B64)
        cobrinhaCache = bmp
        return bmp
    }

    fun frutrisIcon(): Bitmap? {
        frutrisCache?.let { return it }
        val bmp = decode(FRUTRIS_WEBP_B64)
        frutrisCache = bmp
        return bmp
    }

    private fun decode(b64: String): Bitmap? = try {
        val bytes = Base64.decode(b64, Base64.DEFAULT)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
    } catch (t: Throwable) {
        null
    }
}

